fn prove_enum_physical_constructor(
    bytes: &[u8],
    header: &jarde_reader::classfile::MemberHeader,
    identity: PhysicalMethodId,
    pool: &[jarde_reader::classfile::CpEntryFacts],
    enum_owner: &[u8],
    access_descriptor: &[u8],
    parameters: &[crate::enum_constants::EnumUserParameter],
    marker: bool,
    budget: &mut Budget,
) -> Result<std::result::Result<PendingEnumConstructorEdge, String>> {
    use jarde_reader::classfile::{CpEntryKind, cp_entry, method_code_facts};

    if !header
        .attributes
        .iter()
        .any(|attribute| attribute.name.raw().0 == b"Code")
    {
        return Ok(Err("the selected child constructor has no Code".to_owned()));
    }
    budget.charge(CountedBudgetDimension::MethodBodies, 1)?;
    let code = match method_code_facts(bytes, header, budget) {
        Ok(code) => code,
        Err(error @ (Error::BudgetExceeded { .. } | Error::Cancelled { .. })) => return Err(error),
        Err(_) => {
            return Ok(Err(
                "the selected child constructor Code cannot be read".to_owned()
            ));
        }
    };
    match &code.execution {
        ExecutionReport::Cancelled { .. } => {
            return Err(Error::Cancelled {
                reason: "the selected child constructor Code read was cancelled".to_owned(),
            });
        }
        ExecutionReport::Partial {
            reason: TerminationReason::BudgetExceeded { dimension },
            ..
        } => {
            let counted = CountedBudgetDimension::try_from(*dimension).map_err(|()| {
                Error::unsupported(
                    "enum_constructor_code_stop",
                    "the child constructor Code read stopped on an uncounted dimension",
                )
            })?;
            let limit = budget.limits().counted_limit(counted);
            let consumed = match counted {
                CountedBudgetDimension::CodeBytes => budget.usage().code_bytes,
                CountedBudgetDimension::ResultItems => budget.usage().result_items,
                _ => 0,
            };
            return Err(Error::BudgetExceeded {
                dimension: *dimension,
                limit,
                consumed,
                requested: limit.saturating_sub(consumed).saturating_add(1),
            });
        }
        _ => {}
    }
    if code.stopped_at.is_some()
        || !matches!(code.execution, ExecutionReport::Complete { .. })
        || code.exception_handler_count != 0
        || !code.exception_handlers.is_empty()
        || code.instructions.len() != code.operands().len()
        || code
            .instructions
            .last()
            .is_none_or(|last| u64::from(last.bci) + u64::from(last.width) != code.code_span.length)
    {
        return Ok(Err(
            "the selected child constructor Code is incomplete".to_owned()
        ));
    }
    budget.charge(
        CountedBudgetDimension::AnalysisSteps,
        u64::try_from(code.instructions.len()).unwrap_or(u64::MAX),
    )?;
    budget.charge(
        CountedBudgetDimension::IrItems,
        u64::try_from(code.instructions.len()).unwrap_or(u64::MAX),
    )?;
    let mut instructions = Vec::with_capacity(code.instructions.len());
    for (instruction, operands) in code.instructions.iter().zip(code.operands()) {
        budget.poll()?;
        let reference = if let Some(index) = instruction.constant_pool_index {
            match cp_entry(pool, index).map(|entry| &entry.kind) {
                Ok(CpEntryKind::MethodRef {
                    owner,
                    name,
                    descriptor,
                    ..
                }) => Some(crate::enum_constants::EnumCodeReference::Method {
                    owner: owner.0.clone(),
                    name: name.0.clone(),
                    descriptor: descriptor.0.clone(),
                    interface: false,
                }),
                _ => Some(crate::enum_constants::EnumCodeReference::Other),
            }
        } else {
            None
        };
        instructions.push(crate::enum_constants::EnumCodeInstruction {
            bci: instruction.bci,
            width: instruction.width,
            opcode: instruction.opcode,
            immediate: operands.immediate,
            local: operands.local.map(|local| local.index),
            increment: operands.increment,
            interface_count: operands.interface_count,
            reference,
            branch_target_bci: None,
        });
    }
    let result = prove_enum_constructor_instructions(
        &instructions,
        enum_owner,
        access_descriptor,
        parameters,
        marker,
    )
    .map(|call_bci| PendingEnumConstructorEdge {
        caller: identity,
        call_bci,
        target_owner: enum_owner.to_vec(),
        target_descriptor: access_descriptor.to_vec(),
        assigned_field: None,
    });
    Ok(result)
}

#[allow(clippy::too_many_arguments)]
fn resolve_enum_constant_body_relations(
    content: &[ArtifactSnapshot],
    environment: &ResolutionEnvironment,
    enum_nesting: &class_source::ClassSourceAssemblyContext,
    enum_pool: &[jarde_reader::classfile::CpEntryFacts],
    enum_owner: &[u8],
    enum_access_flags: u16,
    enum_interfaces: &[Vec<u8>],
    fields: &[jarde_reader::classfile::MemberHeader],
    source_fields: &[class_source::ClassSourceField],
    methods: &[jarde_reader::classfile::MemberHeader],
    code_candidates: &[crate::enum_constants::EnumMethodCodeCandidate],
    allocation_scans: &[(
        PhysicalMethodId,
        Option<jarde_java::report::AnonymousAllocationScan>,
    )],
    execution: &mut ExecutionReport,
    budget: &mut Budget,
) -> Result<Vec<PendingEnumConstantBodyRelation>> {
    let Some((
        clinit_identity,
        code,
        constructions,
        constant_shape,
        implicit_members,
        source_ctor,
        shared_source_parameters,
        constructors,
        needs_bridge,
        abstract_methods,
        interface_owner,
    )) = jarde_java::source_proof::prepare_enum_body_candidate(
        enum_owner,
        enum_access_flags,
        enum_interfaces,
        fields,
        methods,
        code_candidates,
        allocation_scans,
        budget,
    )?
    else {
        return Ok(Vec::new());
    };
    let mut interface_methods = Vec::new();
    if let Some(interface_owner) = interface_owner {
        let Some((_, interface_read)) = resolve_class_source_dependency_read_raw(
            content,
            environment,
            Some(clinit_identity),
            interface_owner,
            execution,
            budget,
        )?
        else {
            return Ok(Vec::new());
        };
        let Some(member) = jarde_java::source_proof::enum_body_interface_member(
            interface_read.facts.access_flags,
            &interface_read.facts.methods,
        ) else {
            return Ok(Vec::new());
        };
        interface_methods.push(member);
    }
    let Some(group_shape) = jarde_java::source_proof::prove_enum_body_candidate_shape(
        enum_owner,
        enum_access_flags,
        fields,
        methods,
        code_candidates,
        clinit_identity,
        code,
        constant_shape,
        implicit_members,
        &source_ctor,
        &shared_source_parameters,
        constructors,
        needs_bridge,
        abstract_methods,
        interface_methods,
        |index| {
            source_fields
                .get(index)
                .is_some_and(|source| source.declaration.is_some())
        },
        budget,
    )?
    else {
        return Ok(Vec::new());
    };

    let mut relations = Vec::new();
    for (field_index, allocation, constructor_bci, descriptor) in constructions {
        if allocation.class.0.as_slice() == enum_owner {
            continue;
        }
        budget.charge(CountedBudgetDimension::AnalysisSteps, 1)?;
        let Some((definition, child_read)) = resolve_class_source_dependency_read_raw(
            content,
            environment,
            Some(clinit_identity),
            allocation.class.0.as_slice(),
            execution,
            budget,
        )?
        else {
            continue;
        };
        if child_read.facts.stopped_at.is_some()
            || child_read.facts.this_class.raw().0.as_slice() != allocation.class.0.as_slice()
            || child_read
                .facts
                .super_class
                .as_ref()
                .map(|name| name.raw().0.as_slice())
                != Some(enum_owner)
        {
            continue;
        }
        let nesting_shells: Vec<_> = child_read
            .facts
            .attributes
            .iter()
            .filter(|attribute| {
                matches!(
                    attribute.name.raw().0.as_slice(),
                    b"InnerClasses" | b"EnclosingMethod"
                )
            })
            .cloned()
            .collect();
        budget.charge(
            CountedBudgetDimension::AnalysisSteps,
            u64::try_from(nesting_shells.len()).unwrap_or(u64::MAX),
        )?;
        let child_pool = match class_constant_pool(&child_read.bytes, budget) {
            Ok(pool) => pool,
            Err(error @ (Error::BudgetExceeded { .. } | Error::Cancelled { .. })) => {
                return Err(error);
            }
            Err(_) => continue,
        };
        let nesting = match class_source::read_class_source_assembly_context(
            &child_read.bytes,
            &nesting_shells,
            &child_pool,
            budget,
        ) {
            Ok(nesting) => nesting,
            Err(error @ (Error::BudgetExceeded { .. } | Error::Cancelled { .. })) => {
                return Err(error);
            }
            Err(_) => continue,
        };
        let Some((anonymous_inner_owners, child_constructor)) =
            jarde_java::source_proof::prove_enum_constant_child_relation(
                allocation.class.0.as_slice(),
                enum_owner,
                descriptor.as_slice(),
                &child_pool,
                &nesting.inner_classes,
                enum_pool,
                &enum_nesting.inner_classes,
                nesting.enclosing_method.as_ref(),
                &child_read.facts.methods,
                budget,
            )?
        else {
            continue;
        };
        let constructor_bridge = if let Some(access) = group_shape
            .constructors
            .iter()
            .find(|member| member.access_marker_owner.is_some())
        {
            prove_enum_physical_constructor(
                &child_read.bytes,
                child_constructor,
                member_identity(&definition, child_constructor),
                &child_pool,
                enum_owner,
                &access.descriptor,
                &shared_source_parameters,
                true,
                budget,
            )?
        } else {
            Err("the selected child has no unique access constructor target".to_owned())
        };
        let mut child_code_evidence = Ok(());
        for method in &child_read.facts.methods {
            budget.poll()?;
            if method.name.raw().0 == b"<init>" || method.name.raw().0 == b"<clinit>" {
                continue;
            }
            let code =
                match jarde_reader::classfile::method_code_facts(&child_read.bytes, method, budget)
                {
                    Ok(code) => code,
                    Err(error @ (Error::BudgetExceeded { .. } | Error::Cancelled { .. })) => {
                        return Err(error);
                    }
                    Err(error) => {
                        child_code_evidence =
                            Err(format!("child override Code could not be read: {error}"));
                        break;
                    }
                };
            if code.stopped_at.is_some()
                || !matches!(code.execution, ExecutionReport::Complete { .. })
                || code.exception_handler_count != 0
                || !code.exception_handlers.is_empty()
            {
                child_code_evidence =
                    Err("child override has exceptional or incomplete Code".to_owned());
                break;
            }
        }
        relations.push(PendingEnumConstantBodyRelation {
            field_index: u64::try_from(field_index).unwrap_or(u64::MAX),
            allocation_bci: allocation.head_bci,
            constructor_bci,
            constructor_descriptor: descriptor.clone(),
            subclass_owner: allocation.class.0.as_slice().to_vec(),
            subclass: definition,
            anonymous_inner_owners,
            use_census: PendingEnumConstantBodyUseCensus::default(),
            group_shape: group_shape.clone(),
            constructor_bridge,
            child_code_evidence,
            body_proof: None,
        });
    }
    Ok(relations)
}

/// A child is read through the same class-source member path as an independent request. That
/// path prepares its selected definition once and recovers each Code member once; retaining its
/// records here lets the later projection consume the exact declaration and source map already
/// paid for. A body verdict is private and cannot turn the parent group into `Proved` by itself.
fn prove_enum_constant_child_body(
    engine: &Engine,
    content: &[ArtifactSnapshot],
    request: &ClassSourceRequest,
    relation: &PendingEnumConstantBodyRelation,
    enum_methods: &[MemberHeader],
    evidence: &RecoveryEvidenceRequest,
    budget: &mut Budget,
) -> Result<(
    std::result::Result<Vec<ClassSourceMethod>, String>,
    ExecutionReport,
)> {
    let refuse = |reason: &str| Err(reason.to_owned());
    if let Err(reason) = &relation.child_code_evidence {
        return Ok((
            Err(reason.clone()),
            ExecutionReport::Complete {
                usage: budget.usage(),
            },
        ));
    }
    let child_request = ClassSourceRequest {
        source_target: request.source_target,
        class: ClassRef::Definition {
            definition: relation.subclass.clone(),
        },
        environment: request.environment.clone(),
    };
    // Keep the caller's requested publication. Admission reads only same-run core decisions.
    let OperationOutcome::Performed(child) =
        engine.class_source_with_evidence(content, &child_request, evidence, budget)?
    else {
        return Ok((
            refuse("the selected child source is not a unique physical class"),
            ExecutionReport::Complete {
                usage: budget.usage(),
            },
        ));
    };
    let execution = child.execution.clone();
    if !matches!(&execution, ExecutionReport::Complete { .. }) {
        return Ok((
            refuse("the selected child source did not complete"),
            execution,
        ));
    }
    if child.class != relation.subclass {
        return Ok((
            refuse("the selected child source changed physical identity"),
            execution,
        ));
    }
    if let Err(reason) = jarde_java::source_proof::enum_constant_child_header_is_supported(
        child.declaration.is_some(),
        child.fields.len(),
    ) {
        return Ok((refuse(reason), execution));
    }
    let code_count = child
        .methods
        .iter()
        .filter(|method| {
            matches!(
                method.item.body,
                crate::MemberBodyEvidence::CodeAttribute { .. }
            )
        })
        .count();
    let body_runs: Vec<_> = child
        .coverage
        .artifact_structural
        .scanned
        .iter()
        .filter(|range| range.label == "class_source_bodies")
        .collect();
    if !matches!(body_runs.as_slice(), [range] if range.start == 0 && range.end == code_count as u64)
        || child.methods.iter().any(|method| {
            !matches!(
                &method.outcome,
                class_source::ClassSourceOutcome::Recovered { .. }
            )
        })
    {
        return Ok((
            refuse("the selected child did not complete one run per Code member"),
            execution,
        ));
    }
    let expected_constructor = PhysicalMethodId {
        owner: relation.subclass.clone(),
        name: JvmBytes(b"<init>".to_vec()),
        descriptor: JvmBytes(relation.constructor_descriptor.clone()),
    };
    let mut constructors = 0;
    let mut overrides = Vec::new();
    for method in &child.methods {
        budget.poll()?;
        let name = method.item.name.raw().0.as_slice();
        if name == b"<init>" {
            constructors += 1;
            if method.item.identity != expected_constructor
                || method.item.access_flags != 0
                || !matches!(
                    &method.outcome,
                    class_source::ClassSourceOutcome::Recovered { .. }
                )
            {
                return Ok((
                    refuse("the child constructor is not the unique compiler constructor"),
                    execution,
                ));
            }
            continue;
        }
        if name == b"<clinit>" {
            return Ok((
                refuse("the selected child has class initialization"),
                execution,
            ));
        }
        let flags = method.item.access_flags;
        if let Err(reason) =
            jarde_java::source_proof::enum_constant_child_method_is_supported(name, flags)
        {
            return Ok((refuse(reason), execution));
        }
        let matching_base: Vec<_> = enum_methods
            .iter()
            .filter(|base| {
                base.name.raw().0 == name
                    && base.descriptor.raw().0 == method.item.descriptor.raw().0
            })
            .collect();
        let interface_base: Vec<_> = relation
            .group_shape
            .interface_methods
            .iter()
            .filter(|base| base.name == name && base.descriptor == method.item.descriptor.raw().0)
            .collect();
        let base_flags = match (matching_base.as_slice(), interface_base.as_slice()) {
            ([base], []) => base.access_flags,
            ([], [base]) => base.access_flags,
            _ => {
                return Ok((
                    refuse("the selected child method has no unique base declaration"),
                    execution,
                ));
            }
        };
        if !jarde_java::source_proof::enum_constant_child_visibility_is_supported(base_flags, flags)
        {
            return Ok((
                refuse("the child method cannot override its base declaration"),
                execution,
            ));
        }
        if !complete_enum_child_override(method) {
            return Ok((
                refuse("the child override body or declaration is not fully presentable"),
                execution,
            ));
        }
        overrides.push(method.clone());
    }
    if constructors != 1 || overrides.is_empty() {
        return Ok((
            refuse("the child does not have one constructor and source overrides"),
            execution,
        ));
    }
    Ok((Ok(overrides), execution))
}

fn complete_enum_child_override(method: &ClassSourceMethod) -> bool {
    let class_source::ClassSourceOutcome::Recovered { report, analysis } = &method.outcome else {
        return false;
    };
    jarde_java::source_proof::enum_constant_child_recovery_is_supported(
        report,
        &analysis.execution,
        method.declaration.is_some(),
        method.markers.is_empty(),
    )
}

/// Supply the selected root-owned records to Java's complete group policy.
fn prove_enum_constant_body_group(
    declaration: &class_source::ClassSourceDeclaration,
    source_fields: &[ClassSourceField],
    source_methods: &[ClassSourceMethod],
    codes: &[crate::enum_constants::EnumMethodCodeCandidate],
    initializers: &[jarde_java::report::ClassInitializerCandidates],
    relations: &[PendingEnumConstantBodyRelation],
    budget: &mut Budget,
) -> Result<std::result::Result<crate::enum_constants::ProvedEnumConstantBodyGroup, String>> {
    jarde_java::source_proof::prove_enum_constant_body_group(
        (
            declaration.item.declaration.this_class.raw().0.as_slice(),
            &declaration.item.definition,
            &declaration.name,
        ),
        source_fields,
        source_methods,
        codes,
        initializers,
        relations,
        |method| {
            (
                (
                    method.item.index,
                    &method.item.identity,
                    &method.item.name,
                    &method.item.descriptor,
                    matches!(
                        method.item.body,
                        crate::MemberBodyEvidence::CodeAttribute { .. }
                    ),
                    method.no_body_kind,
                    matches!(method.outcome, class_source::ClassSourceOutcome::NoBody),
                    method.declaration.is_some(),
                ),
                match &method.outcome {
                    class_source::ClassSourceOutcome::Recovered { report, analysis } => {
                        Some((report, &analysis.execution))
                    }
                    _ => None,
                },
                (
                    method.markers.as_slice(),
                    method.enum_constructor_source_tail,
                    method.enum_constructor_signature_erasure_refused,
                    &method.annotations,
                    &method.parameter_annotations,
                    &method.type_annotations,
                ),
            )
        },
        |field| {
            (
                &field.item.identity.owner,
                &field.item.name,
                &field.item.descriptor,
                field.item.access_flags,
                field.declaration.is_some(),
                field.markers.as_slice(),
            )
        },
        |relation| {
            (
                &relation.group_shape,
                relation.field_index,
                relation.allocation_bci,
                relation.constructor_bci,
                relation.constructor_descriptor.as_slice(),
                relation.subclass_owner.as_slice(),
                &relation.subclass,
                relation.use_census.exclusive,
                relation.use_census.refusal.is_some(),
                &relation.constructor_bridge,
                relation.body_proof.as_ref(),
            )
        },
        |field_index,
         allocation_bci,
         constructor_bci,
         field_write_bci,
         source_arguments,
         subclass,
         methods| {
            crate::enum_constants::ProvedEnumBodyConstant {
                field_index,
                allocation_bci,
                constructor_bci,
                field_write_bci,
                source_arguments: source_arguments.to_vec(),
                subclass: subclass.cloned(),
                methods: methods.cloned(),
            }
        },
        budget,
    )
    .map(|result| {
        result.map(|(constants, constructor_text, constructor_user_tail)| {
            crate::enum_constants::ProvedEnumConstantBodyGroup {
                constants,
                constructor_text,
                constructor_user_tail,
            }
        })
    })
}

/// Census each selected input through P1's physical scanner. A relation is exclusive only when
/// every selected range was fully read and its entire owner-reference set has an explanation.
/// This says nothing about the constructed object's stack value or constructor arguments.
fn census_enum_constant_body_uses(
    content: &[ArtifactSnapshot],
    environment: &ResolutionEnvironment,
    enum_definition: &PhysicalDefinitionId,
    relations: &mut [PendingEnumConstantBodyRelation],
    execution: &mut ExecutionReport,
    budget: &mut Budget,
) -> Result<()> {
    use jarde_query::query::{XrefCertainty, XrefOperation, XrefTarget};
    use jarde_query::xref::{CandidateFilter, scan_candidates};
    use jarde_reader::model::SymbolRef;

    if relations.is_empty() {
        return Ok(());
    }
    budget.charge(
        CountedBudgetDimension::AnalysisSteps,
        u64::try_from(environment.runtime.load_domain.roots.len() + relations.len())
            .unwrap_or(u64::MAX),
    )?;
    let mut ranges = Vec::<(SnapshotId, PhysicalScope)>::new();
    let mut unscannable_root = false;
    for root in &environment.runtime.load_domain.roots {
        let range = match root {
            LoadRoot::StandaloneClass { snapshot } => {
                Some((snapshot.clone(), PhysicalScope::SnapshotAll))
            }
            LoadRoot::Container { origin, prefix } => {
                // P1 scopes a container tree, not a load-root prefix or one nested path. A
                // wider scan may expose real extra uses, but cannot certify the narrower root.
                if !prefix.0.is_empty() || !origin.steps.is_empty() {
                    unscannable_root = true;
                }
                Some((
                    origin.snapshot.clone(),
                    PhysicalScope::ArtifactTree {
                        root_container: origin.root_container.clone(),
                    },
                ))
            }
            LoadRoot::External { .. } => None,
        };
        if let Some(range) = range {
            if !ranges.contains(&range) {
                ranges.push(range);
            }
        } else {
            unscannable_root = true;
        }
    }
    let consumers = ConsumerSchema::new(
        1,
        [
            ConsumerKind::Invocation,
            ConsumerKind::Field,
            ConsumerKind::Type,
            ConsumerKind::Constant,
            ConsumerKind::Exception,
            ConsumerKind::Signature,
            ConsumerKind::Annotation,
            ConsumerKind::InnerNest,
            ConsumerKind::Module,
            ConsumerKind::Bootstrap,
            ConsumerKind::Resource,
        ],
    );
    let clinit = PhysicalMethodId {
        owner: enum_definition.clone(),
        name: JvmBytes(b"<clinit>".to_vec()),
        descriptor: JvmBytes(b"()V".to_vec()),
    };
    let selected_children: Vec<_> = relations
        .iter()
        .map(|relation| {
            (
                relation.subclass.clone(),
                relation.subclass_owner.clone(),
                relation.anonymous_inner_owners.clone(),
            )
        })
        .collect();
    for relation in relations {
        let census = &mut relation.use_census;
        let mut new_count = 0;
        let mut constructor_count = 0;
        let mut access_descriptor_count = 0;
        if ranges.is_empty() || unscannable_root {
            census.refusal.get_or_insert_with(|| {
                "a selected input root cannot be completely scanned".to_owned()
            });
        }
        for (snapshot_id, scope) in &ranges {
            budget.poll()?;
            let Some(snapshot) = content
                .iter()
                .find(|candidate| candidate.id() == snapshot_id)
            else {
                census
                    .refusal
                    .get_or_insert_with(|| "a selected input snapshot was not provided".to_owned());
                continue;
            };
            let scan = scan_candidates(
                snapshot,
                scope,
                &consumers,
                CandidateFilter::Owner {
                    owner: JvmBytes(relation.subclass_owner.clone()),
                },
                0,
                budget,
            )?;
            let complete = !scan.has_more
                && matches!(&scan.execution, ExecutionReport::Complete { .. })
                && scan.coverage.dimensions.artifact_structural.state
                    == CoverageState::CompleteWithinSchema
                && scan.coverage.unknown_candidates == 0
                && scan.coverage.unsupported_categories.is_empty();
            if !complete {
                census.refusal.get_or_insert_with(|| {
                    "the selected input owner scan is incomplete".to_owned()
                });
            }
            for item in &scan.items {
                let allowed_code = match (&item.source.location, &item.target) {
                    (
                        Location::Code { method, bci },
                        XrefTarget::Symbol {
                            value: SymbolRef::Class { owner },
                        },
                    ) if method == &clinit
                        && *bci == relation.allocation_bci
                        && owner.0 == relation.subclass_owner
                        && item.operation == XrefOperation::New
                        && item.consumer == Some(ConsumerKind::Type)
                        && item.evidence.bci == Some(*bci)
                        && item.evidence.opcode == Some(0xbb) =>
                    {
                        new_count += 1;
                        true
                    }
                    (
                        Location::Code { method, bci },
                        XrefTarget::Symbol {
                            value:
                                SymbolRef::Method {
                                    owner,
                                    name,
                                    descriptor,
                                },
                        },
                    ) if method == &clinit
                        && *bci == relation.constructor_bci
                        && owner.0 == relation.subclass_owner
                        && name.0 == b"<init>"
                        && descriptor.0 == relation.constructor_descriptor
                        && item.operation == XrefOperation::InvokeSpecial
                        && item.consumer == Some(ConsumerKind::Invocation)
                        && item.evidence.bci == Some(*bci)
                        && item.evidence.opcode == Some(0xb7) =>
                    {
                        constructor_count += 1;
                        true
                    }
                    _ => false,
                };
                // 2.1b checked unique typed InnerClasses self rows in both the enum and the
                // child. Those are declaration metadata, not a second object use. Any other
                // class, metadata operation, method, field or handle is additional use.
                let allowed_nesting = matches!(
                    (&item.source.location, &item.target),
                    (
                        Location::ClassOffset { definition, .. },
                        XrefTarget::Symbol {
                            value: SymbolRef::Class { owner },
                        },
                    ) if owner.0 == relation.subclass_owner
                        && item.operation == XrefOperation::InnerClass
                        && item.consumer == Some(ConsumerKind::InnerNest)
                        && (definition == enum_definition
                            || definition == &relation.subclass
                            || selected_children.iter().any(|(selected, _, rows)| {
                                selected == definition
                                    && rows.contains(&relation.subclass_owner)
                            }))
                );
                // 2.1c recorded the one synthetic access constructor and its exact marker
                // owner. P1 reports descriptor types at the UTF8/class coordinate, so require
                // exactly one such item across the census: a second declaration with that
                // descriptor cannot be attributed to the verified bridge.
                let allowed_access_descriptor = matches!(
                    (&item.source.location, &item.target),
                    (
                        Location::ClassOffset { definition, .. },
                        XrefTarget::Symbol {
                            value: SymbolRef::Class { owner },
                        },
                    ) if definition == enum_definition
                        && owner.0 == relation.subclass_owner
                        && item.operation == XrefOperation::MethodDescriptor
                        && item.consumer == Some(ConsumerKind::Type)
                        && relation.group_shape.constructors.iter().any(|constructor| {
                            constructor.access_marker_owner.as_deref()
                                == Some(relation.subclass_owner.as_slice())
                        })
                );
                if allowed_access_descriptor {
                    access_descriptor_count += 1;
                }
                if item.certainty != XrefCertainty::Exact
                    || !(allowed_code || allowed_nesting || allowed_access_descriptor)
                {
                    census.refusal.get_or_insert_with(|| {
                        "the subclass has an additional owner use".to_owned()
                    });
                }
            }
            merge_execution(execution, scan.execution.clone());
            census.scans.push(PendingEnumConstantBodyUseScan {
                snapshot: snapshot_id.clone(),
                scope: scope.clone(),
                items: scan.items,
                has_more: scan.has_more,
                coverage: scan.coverage,
                execution: scan.execution,
                diagnostics: scan.diagnostics,
            });
        }
        if new_count != 1 || constructor_count != 1 {
            census.refusal.get_or_insert_with(|| {
                "the exact enum construction uses were not unique".to_owned()
            });
        }
        let has_access_marker = relation.group_shape.constructors.iter().any(|constructor| {
            constructor.access_marker_owner.as_deref() == Some(relation.subclass_owner.as_slice())
        });
        if access_descriptor_count != usize::from(has_access_marker) {
            census.refusal.get_or_insert_with(|| {
                "the access constructor descriptor use is not unique".to_owned()
            });
        }
        census.exclusive = census.refusal.is_none();
    }
    Ok(())
}

#[cfg(test)]
use jarde_java::source_proof::enum_access_constructor_marker_owner;

/// Selected definitions shared by every interface-super candidate in one method request.
struct InterfaceSuperReads<'a> {
    content: &'a [ArtifactSnapshot],
    environment: &'a ResolutionEnvironment,
    enclosing: &'a PhysicalMethodId,
    budget: &'a mut Budget,
    execution: ExecutionReport,
    attempted: std::collections::BTreeSet<(String, Vec<u8>)>,
    by_name: std::collections::BTreeMap<(String, Vec<u8>), usize>,
    nodes: Vec<SelectedInterfaceNode>,
    inputs: Vec<jarde_java::artifact::ArtifactDependency>,
}

impl InterfaceSuperReads<'_> {
    fn node(&mut self, owner: &[u8], depth: u64) -> DependencyProofResult<Option<usize>> {
        let loader = self.environment.runtime.load_domain.loader.clone();
        self.node_from(&loader, owner, depth)
    }
    fn node_from(
        &mut self,
        loader: &LoaderId,
        owner: &[u8],
        depth: u64,
    ) -> DependencyProofResult<Option<usize>> {
        self.budget.poll()?;
        self.budget.observe_dependency_depth(depth)?;
        let key = (loader.0.clone(), owner.to_vec());
        if let Some(index) = self.by_name.get(&key) {
            return Ok(Some(*index));
        }
        if !self.attempted.insert(key.clone()) {
            return Ok(None);
        }
        self.budget
            .charge(CountedBudgetDimension::AnalysisSteps, 1)?;
        let Some((binding, read)) = resolve_dependency_proof_from(
            self.content,
            self.environment,
            loader,
            Some(self.enclosing),
            owner,
            &mut self.execution,
            self.budget,
            Some(&mut self.inputs),
            None,
        )?
        .found() else {
            return Ok(None);
        };
        if read.facts.stopped_at.is_some() || read.facts.this_class.raw().0.as_slice() != owner {
            return Ok(None);
        }
        if let Some(index) = self
            .nodes
            .iter()
            .position(|node| node.loader == binding.loader && node.definition == binding.definition)
        {
            self.by_name.insert(key, index);
            return Ok(Some(index));
        }
        let index = self.nodes.len();
        self.nodes.push(SelectedInterfaceNode {
            loader: binding.loader,
            definition: binding.definition,
            facts: read.facts,
        });
        self.by_name.insert(key, index);
        Ok(Some(index))
    }
}

/// Add a fully selected interface closure to this request's small graph. The height memo checks
/// the dependency-depth limit even when a diamond reuses a completed node.
#[cfg(test)]
fn ensure_interface_closure(
    owner: &[u8],
    depth: u64,
    reads: &mut InterfaceSuperReads<'_>,
    graph: &mut std::collections::BTreeMap<usize, Vec<usize>>,
    heights: &mut std::collections::BTreeMap<usize, u64>,
    active: &mut Vec<usize>,
) -> DependencyProofResult<bool> {
    reads.budget.poll()?;
    let Some(index) = reads.node(owner, depth)? else {
        return Ok(false);
    };
    ensure_interface_node(index, depth, reads, graph, heights, active)
}

fn ensure_interface_node(
    index: usize,
    depth: u64,
    reads: &mut InterfaceSuperReads<'_>,
    graph: &mut std::collections::BTreeMap<usize, Vec<usize>>,
    heights: &mut std::collections::BTreeMap<usize, u64>,
    active: &mut Vec<usize>,
) -> DependencyProofResult<bool> {
    reads.budget.poll()?;
    if active.contains(&index) {
        return Ok(false);
    }
    if let Some(height) = heights.get(&index) {
        reads
            .budget
            .observe_dependency_depth(depth.saturating_add(*height))?;
        return Ok(true);
    }
    reads.budget.observe_dependency_depth(depth)?;
    let node = &reads.nodes[index];
    if node.facts.access_flags & ACC_INTERFACE == 0 {
        return Ok(false);
    }
    let loader = node.loader.clone();
    let parent_names = node
        .facts
        .interfaces
        .iter()
        .map(|parent| parent.raw().0.clone())
        .collect::<Vec<_>>();
    let mut seen = std::collections::BTreeSet::new();
    let mut parents = Vec::with_capacity(parent_names.len());
    active.push(index);
    let mut height = 0_u64;
    for name in parent_names {
        reads
            .budget
            .charge(CountedBudgetDimension::AnalysisSteps, 1)?;
        if !seen.insert(name.clone()) {
            active.pop();
            return Ok(false);
        }
        let child_depth = depth.saturating_add(1);
        let Some(parent) = reads.node_from(&loader, &name, child_depth)? else {
            active.pop();
            return Ok(false);
        };
        if !ensure_interface_node(parent, child_depth, reads, graph, heights, active)? {
            active.pop();
            return Ok(false);
        }
        height = height.max(heights.get(&parent).copied().unwrap_or(0).saturating_add(1));
        parents.push(parent);
    }
    active.pop();
    graph.insert(index, parents);
    heights.insert(index, height);
    reads
        .budget
        .observe_dependency_depth(depth.saturating_add(height))?;
    Ok(true)
}

/// Retain selected physical inputs without issuing another read. Rejected proof candidates may
/// still have consumed these inputs, so this is a conservative decision-input trace.
fn note_recovery_dependency(
    dependencies: &mut Vec<jarde_java::artifact::ArtifactDependency>,
    loader: &LoaderId,
    definition: &PhysicalDefinitionId,
    budget: &mut Budget,
) -> Result<()> {
    for previous in dependencies.iter() {
        budget.charge(CountedBudgetDimension::AnalysisSteps, 1)?;
        if &previous.loader == loader && &previous.definition == definition {
            return Ok(());
        }
    }
    budget.charge(CountedBudgetDimension::IrItems, 1)?;
    dependencies.push(jarde_java::artifact::ArtifactDependency {
        loader: loader.clone(),
        definition: definition.clone(),
    });
    Ok(())
}

fn prove_interface_super_calls(
    content: &[ArtifactSnapshot],
    request: &crate::ir::MethodAnalysisRequest,
    ir: &jarde_jvm::method_ir::MethodIr,
    dependencies: &mut Vec<jarde_java::artifact::ArtifactDependency>,
    budget: &mut Budget,
) -> DependencyProofResult<Vec<jarde_java::report::InterfaceSuperCallInput>> {
    use std::collections::{BTreeMap, BTreeSet};

    #[cfg(test)]
    interface_super_proof_stop_tests::at_proof_start(request, budget);

    let Some(code) = ir.code() else {
        return Ok(Vec::new());
    };
    let mut candidates = BTreeSet::new();
    for instruction in &code.instructions {
        budget.poll()?;
        budget.charge(CountedBudgetDimension::AnalysisSteps, 1)?;
        if instruction.opcode != 0xb7 {
            continue;
        }
        let Some(index) = instruction.constant_pool_index else {
            continue;
        };
        let Ok(entry) = jarde_reader::classfile::cp_entry(ir.constant_pool(), index) else {
            continue;
        };
        let CpEntryKind::InterfaceMethodRef {
            owner,
            name,
            descriptor,
            ..
        } = &entry.kind
        else {
            continue;
        };
        if ir
            .direct_interfaces()
            .iter()
            .filter(|interface| interface.raw().0 == owner.0)
            .count()
            != 1
        {
            continue;
        }
        candidates.insert((owner.0.clone(), name.0.clone(), descriptor.0.clone()));
    }
    if candidates.is_empty() {
        return Ok(Vec::new());
    }
    let Some(declaration) = ir.declaration() else {
        return Ok(Vec::new());
    };
    let current_class = declaration.class_name().0.as_slice();
    let class_is_interface = declaration.class_access_flags() & ACC_INTERFACE != 0;
    let direct_interfaces = ir
        .direct_interfaces()
        .iter()
        .map(|name| name.raw().0.clone())
        .collect::<Vec<_>>();
    let distinct_direct_interfaces = direct_interfaces.iter().collect::<BTreeSet<_>>();
    if distinct_direct_interfaces.len() != direct_interfaces.len() {
        return Ok(Vec::new());
    }
    let initial_usage = budget.usage();
    let mut reads = InterfaceSuperReads {
        content,
        environment: &request.environment,
        enclosing: &request.method,
        budget,
        execution: ExecutionReport::Complete {
            usage: initial_usage,
        },
        attempted: BTreeSet::new(),
        by_name: BTreeMap::new(),
        nodes: Vec::new(),
        inputs: Vec::new(),
    };
    let mut graph = BTreeMap::new();
    let mut heights = BTreeMap::new();
    let mut active = Vec::new();
    let mut proved = Vec::new();
    for (owner, name, descriptor) in candidates {
        let (raw_owner, name, descriptor) = (JvmBytes(owner), JvmBytes(name), JvmBytes(descriptor));
        let owner = raw_owner.0.as_slice();
        let Some(owner_index) = reads.node(owner, 0)? else {
            continue;
        };
        let owner_flags = reads.nodes[owner_index].facts.access_flags;
        if owner_flags & ACC_INTERFACE == 0
            || !interface_source_type_accessible(current_class, owner, owner_flags)
            || !ensure_interface_node(
                owner_index,
                0,
                &mut reads,
                &mut graph,
                &mut heights,
                &mut active,
            )?
        {
            continue;
        }
        let mut nonredundant = true;
        for direct in &direct_interfaces {
            reads
                .budget
                .charge(CountedBudgetDimension::AnalysisSteps, 1)?;
            if direct.as_slice() == owner {
                continue;
            }
            let Some(direct_index) = reads.node(direct, 0)? else {
                nonredundant = false;
                break;
            };
            if !ensure_interface_node(
                direct_index,
                0,
                &mut reads,
                &mut graph,
                &mut heights,
                &mut active,
            )? || interface_reaches(&direct_index, &owner_index, &graph, reads.budget)?
                != Some(false)
            {
                nonredundant = false;
                break;
            }
        }
        if !nonredundant {
            continue;
        }
        if !class_is_interface {
            let mut parent = ir.direct_super_class().map(|name| name.0.clone());
            let mut seen_classes = BTreeSet::new();
            let mut loader = request.environment.runtime.load_domain.loader.clone();
            let mut depth = 0_u64;
            if parent.is_none() && current_class != b"java/lang/Object" {
                continue;
            }
            let mut class_chain_clear = true;
            while let Some(class_name) = parent {
                reads.budget.poll()?;
                if class_name == b"java/lang/Object" {
                    // `java/lang/Object` is the JVM's fixed root: no host JDK bytes are needed.
                    break;
                }
                if !seen_classes.insert((loader.0.clone(), class_name.clone())) {
                    class_chain_clear = false;
                    break;
                }
                depth = depth.saturating_add(1);
                let Some(class_index) = reads.node_from(&loader, &class_name, depth)? else {
                    class_chain_clear = false;
                    break;
                };
                loader = reads.nodes[class_index].loader.clone();
                let facts = &reads.nodes[class_index].facts;
                if facts.access_flags & ACC_INTERFACE != 0 {
                    class_chain_clear = false;
                    break;
                }
                let implemented = facts
                    .interfaces
                    .iter()
                    .map(|name| name.raw().0.clone())
                    .collect::<Vec<_>>();
                let next_parent = facts.super_class.as_ref().map(|name| name.raw().0.clone());
                let mut seen_implemented = BTreeSet::new();
                for interface in &implemented {
                    reads
                        .budget
                        .charge(CountedBudgetDimension::AnalysisSteps, 1)?;
                    let Some(interface_index) = reads.node_from(&loader, interface, depth)? else {
                        class_chain_clear = false;
                        break;
                    };
                    if !seen_implemented.insert(interface.clone())
                        || !ensure_interface_node(
                            interface_index,
                            depth,
                            &mut reads,
                            &mut graph,
                            &mut heights,
                            &mut active,
                        )?
                        || interface_reaches(&interface_index, &owner_index, &graph, reads.budget)?
                            != Some(false)
                    {
                        class_chain_clear = false;
                        break;
                    }
                }
                if !class_chain_clear {
                    break;
                }
                if next_parent.is_none() {
                    class_chain_clear = false;
                    break;
                }
                parent = next_parent;
            }
            if !class_chain_clear {
                continue;
            }
        }
        let (nodes, proof_budget) = (&reads.nodes, &mut *reads.budget);
        if unique_source_default(
            owner_index,
            &name.0,
            &descriptor.0,
            nodes,
            &graph,
            proof_budget,
        )? && jarde_java::source_proof::source_method_target_is_spellable(
            &raw_owner,
            &name,
            &descriptor,
        ) {
            proved.push(jarde_java::report::InterfaceSuperCallInput {
                owner: raw_owner,
                name,
                descriptor,
            });
        }
    }
    for input in &reads.inputs {
        note_recovery_dependency(dependencies, &input.loader, &input.definition, reads.budget)?;
    }
    Ok(proved)
}

/// Supplies selected facts to Java source proofs; owns no Java applicability decision.
struct RecoveryHeaderReads<'a> {
    content: &'a [ArtifactSnapshot],
    environment: &'a ResolutionEnvironment,
    enclosing: Option<&'a PhysicalMethodId>,
    ir: Option<&'a jarde_jvm::method_ir::MethodIr>,
    cache: &'a mut std::collections::BTreeMap<
        (String, Vec<u8>),
        DependencyResult<ReferenceClassHeader>,
    >,
    execution: &'a mut ExecutionReport,
    inputs: &'a mut Vec<jarde_java::artifact::ArtifactDependency>,
}

impl jarde_java::source_proof::RecoveryHeaders for RecoveryHeaderReads<'_> {
    type Error = DependencyProofFailure;
    fn caller_loader(&self) -> &LoaderId {
        &self.environment.runtime.load_domain.loader
    }
    fn selected_from(
        &mut self,
        loader: &LoaderId,
        owner: &[u8],
        budget: &mut Budget,
    ) -> DependencyProofResult<DependencyResult<ReferenceClassHeader>> {
        let Some(ir) = self.ir else {
            return self.selected_generic_from(loader, owner, budget);
        };
        if let Some(DependencyResult::Found(header)) =
            self.cache.get(&(loader.0.clone(), owner.to_vec()))
        {
            note_recovery_dependency(self.inputs, &header.loader, &header.definition, budget)?;
        }
        selected_dependency_proof_header(
            self.content,
            self.environment,
            self.enclosing,
            ir,
            loader,
            owner,
            self.cache,
            self.execution,
            budget,
            self.inputs,
        )
    }
    fn selected_generic_from(
        &mut self,
        loader: &LoaderId,
        owner: &[u8],
        budget: &mut Budget,
    ) -> DependencyProofResult<DependencyResult<ReferenceClassHeader>> {
        budget.poll()?;
        let key = (loader.0.clone(), owner.to_vec());
        if let Some(cached) = self.cache.get(&key) {
            match cached {
                DependencyResult::Found(header) if header.generic_signatures.is_some() => {
                    note_recovery_dependency(
                        self.inputs,
                        &header.loader,
                        &header.definition,
                        budget,
                    )?;
                    return Ok(cached.clone());
                }
                DependencyResult::Missing | DependencyResult::Ambiguous => {
                    return Ok(cached.clone());
                }
                DependencyResult::Found(_) | DependencyResult::Unknown => {}
            }
        }
        let selected = match resolve_dependency_proof_from(
            self.content,
            self.environment,
            loader,
            self.enclosing,
            owner,
            self.execution,
            budget,
            Some(self.inputs),
            self.ir,
        )? {
            DependencyResult::Found((binding, read)) => {
                let Some(header) = ReferenceClassHeader::from_facts(
                    &read.facts,
                    binding.loader,
                    binding.definition,
                ) else {
                    return Ok(DependencyResult::Unknown);
                };
                let pool = jarde_reader::classfile::class_constant_pool(&read.bytes, budget)?;
                match header.with_generic_signatures(
                    &read.bytes,
                    &read.facts.attributes,
                    &pool,
                    budget,
                ) {
                    Ok(header) => DependencyResult::Found(header),
                    Err(error) if error_ends_the_request(&error, budget) => {
                        return Err(error.into());
                    }
                    Err(_) => DependencyResult::Unknown,
                }
            }
            DependencyResult::Missing => DependencyResult::Missing,
            DependencyResult::Ambiguous => DependencyResult::Ambiguous,
            DependencyResult::Unknown => DependencyResult::Unknown,
        };
        if !matches!(selected, DependencyResult::Unknown) {
            self.cache.insert(key, selected.clone());
        }
        Ok(selected)
    }
    fn resolve_member(
        &mut self,
        symbol: &jarde_reader::model::SymbolRef,
        use_kind: jarde_jvm::resolver::ReferenceUse,
        budget: &mut Budget,
    ) -> DependencyProofResult<DependencyResult<jarde_jvm::resolver::ResolvedMemberRef>> {
        budget.poll()?;
        let request = ResolutionRequest {
            environment: self.environment.clone(),
            target: symbol.clone(),
            use_kind,
            caller: jarde_jvm::environment::CallerContext {
                loader: self.caller_loader().clone(),
                enclosing: self.enclosing.cloned(),
            },
            dispatch: None,
        };
        let resolution = match self.ir {
            Some(ir) => jarde_jvm::resolve_symbol_from_ir(self.content, &request, ir, budget)?,
            None => jarde_jvm::resolve_symbol(self.content, &request, budget)?,
        };
        merge_execution(self.execution, resolution.execution.clone());
        if ends_the_request(&resolution.execution) {
            return Err(DependencyProofFailure::Report {
                execution: Box::new(resolution.execution),
                diagnostics: resolution.diagnostics,
            });
        }
        for read in &resolution.reads {
            note_recovery_dependency(self.inputs, &read.loader, &read.definition, budget)?;
        }
        Ok(match dependency_resolution(&resolution) {
            DependencyResult::Found(()) => resolution
                .resolved
                .map_or(DependencyResult::Unknown, DependencyResult::Found),
            DependencyResult::Missing => DependencyResult::Missing,
            DependencyResult::Ambiguous => DependencyResult::Ambiguous,
            DependencyResult::Unknown => DependencyResult::Unknown,
        })
    }
    fn platform_unprovided(
        &mut self,
        owner: &[u8],
        budget: &mut Budget,
    ) -> DependencyProofResult<bool> {
        platform_class_unprovided(
            self.content,
            self.environment,
            self.enclosing,
            owner,
            budget,
            self.inputs,
        )
    }
}

fn selected_dependency_proof_header(
    content: &[ArtifactSnapshot],
    environment: &ResolutionEnvironment,
    enclosing: Option<&PhysicalMethodId>,
    ir: &jarde_jvm::method_ir::MethodIr,
    loader: &LoaderId,
    owner: &[u8],
    cache: &mut std::collections::BTreeMap<
        (String, Vec<u8>),
        DependencyResult<ReferenceClassHeader>,
    >,
    execution: &mut ExecutionReport,
    budget: &mut Budget,
    inputs: &mut Vec<jarde_java::artifact::ArtifactDependency>,
) -> DependencyProofResult<DependencyResult<ReferenceClassHeader>> {
    #[cfg(test)]
    if let Some(method) = enclosing
        && cache.contains_key(&(loader.0.clone(), owner.to_vec()))
    {
        class_source_proof_inflight_tests::note_header_hit(method, owner);
    }
    selected_reference_header_with(
        ir,
        &environment.runtime.load_domain.loader,
        loader,
        owner,
        cache,
        budget,
        |budget| {
            #[cfg(test)]
            if let Some(method) = enclosing {
                class_source_proof_inflight_tests::note_header_read(method, owner);
            }
            resolve_dependency_proof_from(
                content,
                environment,
                loader,
                enclosing,
                owner,
                execution,
                budget,
                Some(inputs),
                Some(ir),
            )
        },
    )
}

fn selected_reference_header_with<E: From<Error>>(
    ir: &jarde_jvm::method_ir::MethodIr,
    caller_loader: &LoaderId,
    loader: &LoaderId,
    owner: &[u8],
    cache: &mut std::collections::BTreeMap<
        (String, Vec<u8>),
        DependencyResult<ReferenceClassHeader>,
    >,
    budget: &mut Budget,
    mut read: impl FnMut(
        &mut Budget,
    ) -> std::result::Result<
        DependencyResult<(jarde_jvm::resolver::ResolvedMemberRef, ConfirmedRead)>,
        E,
    >,
) -> std::result::Result<DependencyResult<ReferenceClassHeader>, E> {
    budget.poll()?;
    budget.charge(CountedBudgetDimension::AnalysisSteps, 1)?;
    let key = (loader.0.clone(), owner.to_vec());
    if let Some(cached) = cache.get(&key) {
        return Ok(cached.clone());
    }
    let current = ir
        .declaration()
        .map(|declaration| declaration.class_name().0.as_slice());
    let selected = if loader == caller_loader && current == Some(owner) {
        ReferenceClassHeader::from_ir(ir, loader.clone())
            .map_or(DependencyResult::Unknown, DependencyResult::Found)
    } else {
        match read(budget)? {
            DependencyResult::Found((binding, read)) => {
                ReferenceClassHeader::from_facts(&read.facts, binding.loader, binding.definition)
                    .map_or(DependencyResult::Unknown, DependencyResult::Found)
            }
            DependencyResult::Missing => DependencyResult::Missing,
            DependencyResult::Ambiguous => DependencyResult::Ambiguous,
            DependencyResult::Unknown => DependencyResult::Unknown,
        }
    };
    // The cache is scoped to this immutable request and full environment. Completed absence or
    // ambiguity may be reused; Unknown and stopped/incomplete reads never become negative facts.
    if !matches!(selected, DependencyResult::Unknown) {
        cache.insert(key, selected.clone());
    }
    Ok(selected)
}

/// The Java runtime fact is usable only when the selected order proves that it supplies no
/// competing definition. A failed or ambiguous read is not evidence of absence.
fn platform_class_unprovided(
    content: &[ArtifactSnapshot],
    environment: &ResolutionEnvironment,
    enclosing: Option<&PhysicalMethodId>,
    owner: &[u8],
    budget: &mut Budget,
    inputs: &mut Vec<jarde_java::artifact::ArtifactDependency>,
) -> DependencyProofResult<bool> {
    let resolution = jarde_jvm::resolve_symbol(
        content,
        &ResolutionRequest {
            environment: environment.clone(),
            target: jarde_reader::model::SymbolRef::Class {
                owner: JvmBytes(owner.to_vec()),
            },
            use_kind: ReferenceUse::ClassReference,
            caller: jarde_jvm::environment::CallerContext {
                loader: environment.runtime.load_domain.loader.clone(),
                enclosing: enclosing.cloned(),
            },
            dispatch: None,
        },
        budget,
    )?;
    #[cfg(test)]
    class_source_proof_inflight_tests::note_original_report(
        enclosing,
        &resolution.execution,
        &resolution.diagnostics,
        budget,
    );
    if ends_the_request(&resolution.execution) {
        return Err(DependencyProofFailure::Report {
            execution: Box::new(resolution.execution),
            diagnostics: resolution.diagnostics,
        });
    }
    for read in &resolution.reads {
        note_recovery_dependency(inputs, &read.loader, &read.definition, budget)?;
    }
    Ok(matches!(
        dependency_resolution(&resolution),
        DependencyResult::Missing
    ))
}

