#[cfg(test)]
mod reference_overload_tests {
    use super::*;

    fn jvm_string(text: &str) -> JvmString {
        serde_json::from_value(serde_json::json!({
            "raw": text.as_bytes(),
            "utf16": text.encode_utf16().collect::<Vec<_>>(),
            "escaped": text,
        }))
        .unwrap()
    }

    fn method(descriptor: &str, flags: u16) -> MemberHeader {
        MemberHeader {
            name: jvm_string("take"),
            descriptor: jvm_string(descriptor),
            access_flags: flags,
            attributes: Vec::new(),
        }
    }

    #[test]
    fn exact_target_refuses_same_formal_ambiguity_and_bridge() {
        let descriptor = b"(Lpkg/Base;)Ljava/lang/String;";
        let target = b"pkg/Base";
        let mut budget = task_budget(&[]).unwrap();
        let count = |methods: &[MemberHeader], budget: &mut Budget| {
            exact_reference_overload_count(methods, b"take", descriptor, target, true, budget)
                .unwrap()
        };
        let original = method("(Lpkg/Base;)Ljava/lang/String;", 0x0009);
        assert_eq!(count(std::slice::from_ref(&original), &mut budget), Some(1));
        assert_eq!(
            count(&[original.clone(), original.clone()], &mut budget),
            Some(2)
        );
        assert_eq!(
            count(
                &[
                    original.clone(),
                    method("(Lpkg/Base;)Ljava/lang/Object;", 0x0009)
                ],
                &mut budget
            ),
            None
        );
        assert_eq!(
            count(
                &[original, method("(Lpkg/Base;)Ljava/lang/String;", 0x0049)],
                &mut budget
            ),
            None
        );
    }

    #[test]
    fn private_target_keeps_a_binding_with_b_overload_and_refuses_bad_declarations() {
        let a = method("(Lpkg/A;)I", 0x000a);
        let b = method("(Lpkg/B;)I", 0x000a);
        let mut budget = task_budget(&[]).unwrap();
        let check = |methods: &[MemberHeader], budget: &mut Budget| {
            exact_private_reference_target(methods, b"take", b"(Lpkg/A;)I", b"pkg/A", budget)
                .unwrap()
        };
        assert!(check(&[a.clone(), b], &mut budget));
        assert!(!check(&[a.clone(), a.clone()], &mut budget));
        assert!(!check(&[method("(Lpkg/A;)I", 0x0009)], &mut budget));
        assert!(!check(&[method("(Lpkg/A;)I", 0x100a)], &mut budget));
        assert!(!check(&[method("(Lpkg/A;)Z", 0x000a)], &mut budget));
        let mut limits = task_budget(&[]).unwrap().limits().clone();
        limits.analysis_steps = 0;
        assert!(matches!(
            exact_private_reference_target(
                &[a.clone()],
                b"take",
                b"(Lpkg/A;)I",
                b"pkg/A",
                &mut Budget::new(limits)
            ),
            Err(Error::BudgetExceeded { .. })
        ));
        let cancellation = jarde_reader::budget::CancellationToken::new();
        cancellation.cancel();
        let mut cancelled = Budget::with_cancellation_token(
            task_budget(&[]).unwrap().limits().clone(),
            cancellation,
        );
        assert!(matches!(
            exact_private_reference_target(&[a], b"take", b"(Lpkg/A;)I", b"pkg/A", &mut cancelled),
            Err(Error::Cancelled { .. })
        ));
    }
}

