fn reference_parameter_sites<'a>(
    descriptor: &'a [u8],
    receiver_slots: usize,
    budget: &mut Budget,
) -> Option<Vec<(usize, &'a [u8])>> {
    reference_parameter_sites_checked(descriptor, receiver_slots, budget)
        .ok()
        .flatten()
}

