    fn assert_raw_member_path(
        jar: &[u8],
        descriptor: &str,
        expected_owner: &str,
        expected_path: &[&str],
    ) {
        let (snapshot, request, analyzed, context) = named_fixture(jar, "p/Use", descriptor);
        let targets = read_class_source_member_inner_targets(
            std::slice::from_ref(&snapshot),
            &request,
            analyzed.ir(),
            &context,
            &mut Vec::new(),
            &mut test_budget(),
        )
        .unwrap();
        let [target] = targets.as_slice() else {
            panic!("one exact raw member target is required: {targets:?}");
        };
        assert_eq!(
            serde_json::to_value(&target.owner).unwrap(),
            serde_json::to_value(JvmBytes::from_unicode(expected_owner)).unwrap()
        );
        assert_eq!(
            target
                .source_type_path
                .iter()
                .map(|s| s.source_name.as_str())
                .collect::<Vec<_>>(),
            expected_path
        );
        let code = analyzed.ir().code().unwrap();
        let pool = analyzed.ir().constant_pool();
        assert!(
            code.instructions
                .iter()
                .filter_map(|i| i.constant_pool_index)
                .any(|index| {
                    matches!(jarde_reader::classfile::cp_entry(pool, index).map(|e| &e.kind),
                Ok(jarde_reader::classfile::CpEntryKind::MethodRef { owner, name, .. })
                    if owner == &JvmBytes::from_unicode(expected_owner) && name.0 == b"<init>")
                })
        );
    }

