    #[cfg(feature = "test-support")]
    fn helper_work(o: &Observation) -> (u64, [u64; 6]) {
        let (_, before) = o.at_prepared.as_ref().unwrap();
        let (_, after) = o.at_maps.as_ref().unwrap();
        let (body_before, ir_before) = before.unwrap();
        let (body_after, ir_after) = after.unwrap();
        (
            body_after - body_before,
            std::array::from_fn(|i| ir_after[i] - ir_before[i]),
        )
    }
    #[cfg(feature = "test-support")]
